package java.util;
public class Vector<E> extends ArrayList<E> implements java.io.Serializable { private int capacity,increment; public Vector(){super(10);capacity=10;}public Vector(int n){this(n,0);}public Vector(int n,int increment){super(n);capacity=n;this.increment=increment;}public Vector(Collection<? extends E> c){super(c);capacity=c.size();}public synchronized int capacity(){return capacity;}public synchronized void ensureCapacity(int n){if(n>capacity){capacity=Math.max(n,capacity+(increment>0?increment:capacity));super.ensureCapacity(capacity);}}public synchronized void trimToSize(){super.trimToSize();capacity=size();}public synchronized void copyInto(Object[] a){for(int i=0;i<size();i++)a[i]=get(i);}public synchronized Object clone(){Vector<E> v=new Vector<E>(capacity,increment);v.addAll(this);return v;}public synchronized void addElement(E e){add(e);}public synchronized E elementAt(int i){return get(i);}public synchronized void setElementAt(E e,int i){set(i,e);}public synchronized void removeElementAt(int i){remove(i);}public synchronized boolean removeElement(Object e){return remove(e);}public synchronized void removeAllElements(){clear();}public synchronized E firstElement(){if(isEmpty())throw new NoSuchElementException();return get(0);}public synchronized E lastElement(){if(isEmpty())throw new NoSuchElementException();return get(size()-1);}public synchronized void insertElementAt(E e,int i){add(i,e);}public synchronized void setSize(int n){if(n<0)throw new ArrayIndexOutOfBoundsException();while(size()>n)remove(size()-1);while(size()<n)add(null);}public Enumeration<E> elements(){return new Enumeration<E>(){int i;public boolean hasMoreElements(){return i<size();}public E nextElement(){if(!hasMoreElements())throw new NoSuchElementException();return get(i++);}};} }
